import{l as e,t}from"./router-C3INevYe.js";import{s as n}from"./index-B-hvqcqI.js";var r=e(),i=[{id:`harassment`,title:`Don’t harass people.`,body:`Disagree as hard as you like with ideas. Don’t target people: no pile-ons, no repeated unwanted contact, no encouraging others to go after someone, no slurs or insults aimed at a person.`,examples:[`Replying to every post someone makes after they’ve asked you to stop`,`Making new accounts to reach someone who blocked you`]},{id:`hate`,title:`No hateful conduct.`,body:`Don’t attack, dehumanise or call for exclusion of people based on race, ethnicity, national origin, caste, religion, disability, disease, age, sex, gender identity or sexual orientation. Discussing these topics is fine; demeaning people for who they are is not.`},{id:`violence`,title:`No threats or glorified violence.`,body:`No threats against anyone, including “jokes” that read as threats. Don’t celebrate or encourage violence, terrorism or self-harm. If you’re struggling, posting about it is welcome — we’ll never remove someone for asking for help.`},{id:`minors`,title:`Zero tolerance for sexual content involving minors.`,body:`Any sexualised content involving anyone under 18 — real, drawn or generated — is removed immediately, the account is permanently suspended, and we report it to the relevant authorities. There are no warnings and no appeals for this rule.`},{id:`intimate`,title:`No intimate media without consent.`,body:`Never share or threaten to share private sexual images or videos of someone without their clear consent, including fakes. Links to such material count too.`},{id:`spam`,title:`No spam or manipulation.`,body:`Don’t post the same thing over and over, run fake or coordinated accounts, buy or sell engagement, or use automation to flood mentions and replies. Relay’s feeds are chronological, so there’s no algorithm to game — please don’t try to game people instead.`},{id:`impersonation`,title:`Be who you say you are — or say you’re not.`,body:`Don’t pretend to be another person or organisation in a way that could mislead. Parody and fan accounts are fine when they say so clearly in the name or bio.`},{id:`privacy`,title:`Don’t share people’s private information.`,body:`No doxxing: home addresses, private phone numbers, ID documents, financial details, or anything that would let someone be found or harmed without their consent. Encouraging others to dig this up counts too.`},{id:`illegal`,title:`No illegal goods or services.`,body:`Don’t use Relay to sell, buy or arrange weapons, drugs, stolen data, counterfeit documents or other illegal goods and services, or to promote scams and fraud.`}];function a(e){return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n,{title:`Community rules`,back:`/`}),(0,r.jsxs)(`article`,{className:`prose`,children:[(0,r.jsxs)(`header`,{className:`prose-head`,children:[(0,r.jsx)(`p`,{className:`kicker`,children:`Relay · community rules`}),(0,r.jsx)(`h2`,{className:`prose-title`,children:`Be someone people are glad to read.`}),(0,r.jsx)(`p`,{className:`prose-lede`,children:`Relay is a shared space for writing and conversation. These rules are short on purpose: they describe what gets content removed or accounts suspended. Everything else is up to you — and to the tools you have for shaping your own feed.`})]}),(0,r.jsx)(`ol`,{className:`rules-list`,children:i.map((e,t)=>(0,r.jsxs)(`li`,{id:`rule-${e.id}`,className:`rule-item`,children:[(0,r.jsx)(`span`,{className:`rule-num`,"aria-hidden":`true`,children:String(t+1).padStart(2,`0`)}),(0,r.jsxs)(`div`,{children:[(0,r.jsx)(`h3`,{children:e.title}),(0,r.jsx)(`p`,{children:e.body}),e.examples&&(0,r.jsx)(`ul`,{className:`rule-examples`,children:e.examples.map(e=>(0,r.jsx)(`li`,{children:e},e))})]})]},e.id))}),(0,r.jsxs)(`section`,{className:`prose-section`,"aria-labelledby":`enforcement`,children:[(0,r.jsx)(`h2`,{id:`enforcement`,children:`What happens when a rule is broken`}),(0,r.jsxs)(`dl`,{className:`prose-dl`,children:[(0,r.jsx)(`dt`,{children:`Post removal`}),(0,r.jsx)(`dd`,{children:`A moderator removes the post. It’s replaced with a note saying it was removed for breaking the rules, so replies keep their context. The action is logged.`}),(0,r.jsx)(`dt`,{children:`Suspension`}),(0,r.jsx)(`dd`,{children:`For serious or repeated breaches, the account is suspended: it’s signed out everywhere, its posts are hidden, and its profile shows that it’s suspended. Breaking the rule on minors always means permanent suspension.`})]}),(0,r.jsx)(`p`,{children:`Moderators are people, not an algorithm. Every action they take is recorded in a moderation log, and moderators can’t act against admins.`})]}),(0,r.jsxs)(`section`,{className:`prose-section`,"aria-labelledby":`reporting`,children:[(0,r.jsx)(`h2`,{id:`reporting`,children:`How to report`}),(0,r.jsxs)(`p`,{children:[`Open the `,(0,r.jsx)(`strong`,{children:`⋯`}),` menu on any post and choose `,(0,r.jsx)(`em`,{children:`Report post`}),`, or use the menu on someone’s profile to report the account. Pick the reason that fits best and add any context that helps. Reports are private: the person you report is never told who reported them. Reporting the same thing twice doesn’t speed it up, but reporting different posts does help us see a pattern.`]})]}),(0,r.jsxs)(`section`,{className:`prose-section`,"aria-labelledby":`tools`,children:[(0,r.jsx)(`h2`,{id:`tools`,children:`Blocks and mutes`}),(0,r.jsxs)(`dl`,{className:`prose-dl`,children:[(0,r.jsx)(`dt`,{children:`Mute`}),(0,r.jsx)(`dd`,{children:`Quietly removes someone from your feeds, Explore, search and notifications. They aren’t told, can still follow you and can still see your posts. You can still open their profile and see them in threads.`}),(0,r.jsx)(`dt`,{children:`Block`}),(0,r.jsx)(`dd`,{children:`A wall in both directions. Neither of you can see the other’s posts, follow, reply, mention-notify or message. Any follows between you are removed. They aren’t notified, though they may notice they can’t see you.`}),(0,r.jsx)(`dt`,{children:`Muted words`}),(0,r.jsxs)(`dd`,{children:[`Hide posts containing words or phrases you’d rather not see, from your feeds, Explore and search. Manage them in`,` `,(0,r.jsx)(t,{to:`/settings/muting`,children:`Settings → Muting`}),`.`]})]})]}),(0,r.jsxs)(`footer`,{className:`prose-foot meta`,children:[`These rules may be updated as Relay grows; meaningful changes will be announced, not slipped in. See also`,` `,(0,r.jsx)(t,{to:`/about`,children:`About Relay`}),`.`]})]})]})}export{a as default};
